from Crypto.Util.number import *

def get_nextprime(n):
    if n < 2: return 2
    n += 1
    if n % 2 == 0:
        n += 1
    while not isPrime(n):
        n += 2
    return n

flag = b'whuctf{???????????????}'
m = bytes_to_long(flag)

mid = getPrime(280) << 744
p = get_nextprime(mid + getPrime(819))
q = get_nextprime(mid + getPrime(819))

n = p * q
d = getPrime(640)

phi = (p - 1) * (q - 1)
e = inverse(d, phi)

c = pow(m, e, n)

print(f'c = {c}')
print(f'e = {e}')
print(f'n = {n}')

